INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97531, 'spa', 'herencia, patrimonio', 'herencia, patrimonio');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97544, 'spa', 'Porción asignada', 'Porción designada o parte otorgada. Esdras 4:16 habla de la «porción» territorial más allá del río que podría perderse si Jerusalén fuera reconstruida. Daniel 4:15, 23 (arameo 4:12, 20) describen «su porción» junto a las bestias del campo como parte de la humillación de Nabucodonosor. El significado fundamental es el de una participación asignada o distribuida con autoridad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97545, 'spa', 'Liso, lisonjero', 'Liso, suave — desde la textura física hasta la adulación engañosa. Génesis 27:11 describe a Jacob como אִישׁ חָלָק (''hombre de piel lisa'') frente al velludo Esaú. En sentido figurado, Proverbios 5:3 advierte que el paladar de la mujer ajena es ''más suave que el aceite'', y Proverbios 26:28 vincula la ''lengua suave'' con la mentira. Ezequiel 12:24 condena la ''adivinación lisonjera''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97549, 'spa', 'Una parcela, campo o porción concreta de terreno agrícola', 'Una parcela, campo o porción concreta de terreno agrícola. Las traducciones al español como campo y al alemán como Feld confirman que se trata de tierra física. Jacob comprando una חֶלְקַת הַשָּׂדֶה en Siquem (Gn 33:19; Jos 24:32), Rut espigando en el campo de Booz (Rt 2:3; 4:3) y la parcela ensangrentada de la viña de Nabot (2 R 9:21, 25-26) ejemplifican veinte ocurrencias de territorio tangible.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97558, 'spa', 'Una parte asignada, porción hereditaria o asignación — enfatizando la posesión l', 'Una parte asignada, porción hereditaria o asignación — enfatizando la posesión legítima más que la geografía física. Las traducciones al español como porción y al alemán como Anteil señalan la dimensión abstracta. La porción reservada del líder en la bendición de Moisés (Dt 33:21), los malvados cuya ''porción es maldita'' (Job 24:18) y Dios lamentando que ''mi porción'' fue pisoteada (Jer 12:10) ilustran tres ocurrencias.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97565, 'spa', 'Suavidad, lisonja', 'Suavidad en el habla, lisonja o elocuencia engañosa. Es el sentido predominante en cuatro apariciones (Sal 12:2-3; Pr 6:24; Is 30:10). Las «lisonjas» destacan la cualidad seductora y persuasiva. En Isaías 30:10, el pueblo exige profecías agradables, prefiriendo el engaño cómodo a la verdad incómoda.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97566, 'spa', 'Parte lisa del cuerpo', 'La parte suave y lampiña del cuerpo, específicamente la piel del cuello de Jacob en Génesis 27:16. La «suavidad» retiene la cualidad táctil y física. Rebeca cubrió esta piel lisa con pelo de cabra para que Isaac, ciego, fuera engañado, vinculando la suavidad física al tema más amplio del engaño que impregna el campo semántico de esta palabra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97569, 'spa', 'Lugares resbaladizos', 'Lugares resbaladizos o terreno traicionero donde se pierde el equilibrio. En Salmo 73:18, Dios pone a los malvados en lugares resbaladizos para que caigan a la destrucción. La percepción del salmista es que la aparente prosperidad es terreno inestable, y la metáfora de suavidad como peligro completa el arco desde la lisonja hasta lo físico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97574, 'spa', 'Hilcías (nombre propio)', 'Hilcías (nombre propio): el nombre propio masculino Hilcías (חִלְקִיָּהוּ / חִלְקִיָּה), que significa ''mi porción es YHWH'', llevado por varias figuras bíblicas. El más notable es el sumo sacerdote que halló el rollo de la Torá durante la reparación del templo bajo Josías (2 R 22:4, 8; 2 Cr 34:14-15), el padre de Eliaquim bajo Ezequías (2 R 18:18, 26; Is 36:3) y el padre del profeta Jeremías (Jer 1:1). También designa a varios levitas y un sacerdote postexílico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97581, 'spa', 'Resbaladero, intrigas', 'Resbaladero o terreno traicionero, usado metafóricamente para un camino peligroso e inestable. En el Salmo 35:6 el salmista pide que el camino de sus enemigos sea oscuro y resbaladizo, y Jeremías 23:12 advierte que la senda de los falsos profetas será como piso resbaladizo en la oscuridad. En Daniel 11:21 y 11:34 el sentido se desplaza hacia las intrigas políticas y la adulación calculada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97584, 'spa', 'Debilitar o postrar', 'Debilitar, postrar o incapacitar. Éxodo 17:13 relata cómo «Josué debilitó a Amalec» en batalla. Job 14:10 lo emplea para la muerte humana: «el hombre muere y queda postrado», subrayando la finalidad. Isaías 14:12 describe a Babilonia como «debilitador de naciones» antes de su propia caída. El significado central es reducir la fuerza hasta la impotencia total.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97586, 'spa', 'Suegro paterno', 'El padre del esposo de una mujer, es decir, el suegro por línea del marido. En Génesis 38, Judá ocupa esta relación con Tamar, y la tensión narrativa gira en torno a esa obligación de parentesco. En 1 Samuel 4:19 y 4:21, Elí es identificado con este término en el momento de su muerte, intensificando el patetismo de la escena.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97588, 'spa', 'Cam (nombre propio)', 'Cam (nombre propio): el nombre propio Cam (חָם I), segundo hijo de Noé y antepasado epónimo de los pueblos del sur y de África. Aparece en la narrativa del diluvio como uno de los tres sobrevivientes a bordo del arca con Noé (Gn 5:32; 6:10; 7:13; 9:18) y es llamado padre de Canaán (Gn 9:22). La Tabla de las Naciones traza cuatro linajes desde Cam — Cus, Mizraim, Fut y Canaán (Gn 10:1, 6, 20; 1 Cr 1:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97590, 'spa', 'Calor del día o sol', 'Calor atmosférico o solar, el sentido dominante en doce ocurrencias. Es el sofocante calor del mediodía levantino: Abraham recibiendo visitantes ''en el calor del día'' (Gn 18:1), el ritmo estacional de ''frío y calor'' (Gn 8:22) y el peligroso sol de la cosecha que marchita las plantas sin raíz (Jer 17:8; Is 18:4). Se traduce directamente como intensidad climática.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97598, 'spa', 'Inflamado de pasión', 'Calor figurado como pasión inflamada, aparece una vez en Jeremías 51:39 donde los líderes de Babilonia están encendidos por la bebida antes de que caiga el juicio divino. La expresión ''en su calor'' preserva la metáfora que vincula la temperatura física con el arrebato de la embriaguez y la emoción temeraria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97600, 'spa', 'Caliente al tacto', 'La temperatura de un objeto físico, específicamente el pan caliente de 1 Samuel 21:7, donde el sacerdote de Nob ofrece a David ''pan caliente'' recién retirado de la presencia del SEÑOR. Apunta a la calidez táctil, no al calor atmosférico ni emocional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97601, 'spa', 'Calor corporal', 'Calidez corporal como confort o su ausencia, encontrado en Hageo 1:6, donde el profeta lamenta que el pueblo ''se viste, pero nadie entra en calor.'' Este sentido se centra en la tibieza que el cuerpo necesita para prosperar, distinta del calor externo del sol o del horno.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97605, 'spa', 'Cuajada / leche cuajada', 'Producto lácteo espeso -- cuajada, nata coagulada o sustancia semejante a la mantequilla -- obtenido al batir o dejar espesar naturalmente la leche de vacas u ovejas. Indicador de abundancia pastoral y hospitalidad generosa: Abraham la sirve a los visitantes divinos (Gn 18:8), Jael la ofrece a Sísara (Jue 5:25) y simboliza la riqueza de la tierra prometida (Dt 32:14). También se emplea en la sabiduría proverbial sobre causa y efecto (Pr 30:33).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97611, 'spa', 'El sentido activo primario', 'El sentido activo primario: desear, codiciar o anhelar algo. Este es el verbo del Decálogo (Éx 20:17; Dt 5:21), donde denota un deseo pecaminoso e incontrolado por las posesiones del prójimo. Sin embargo, el contexto puede suavizarlo a un anhelo neutro, como en Josué 7:21 donde Acán confiesa ''los codicié''. El español ''codiciar'' y el francés ''convoiter'' marcan sistemáticamente este deseo adquisitivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97612, 'spa', 'El participio pasivo Qal usado sustantivamente para designar una cosa preciosa, ', 'El participio pasivo Qal usado sustantivamente para designar una cosa preciosa, un tesoro o un deleite. En Job 20:20 y el Salmo 39:11 se refiere a lo que una persona atesora o estima. El alemán ''Schatz'' (tesoro) y el español ''cosas preciadas'' confirman la lectura sustantival, donde el acto de desear se ha cristalizado en el objeto deseado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97613, 'spa', 'El sentido participial Nifal', 'El sentido participial Nifal: deseable, agradable, digno de ser deseado. Aquí el verbo funciona como adjetivo, describiendo objetos que atraen o deleitan. Génesis 2:9 lo usa para los árboles del Edén, y el Salmo 19:10 para las ordenanzas de Dios como ''más deseables que el oro''. El español ''deseable'' y el alemán ''lieblich'' (encantador) muestran el paso del deseo adquisitivo a la apreciación estética o espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97617, 'spa', 'El sentido intensivo Piel', 'El sentido intensivo Piel: deleitarse intensamente, expresando un deseo elevado o concentrado. Se encuentra únicamente en Cantares 2:3, donde la amada se deleita sentada a la sombra de su amado. El español ''deseé'' y el francés ''j''ai désiré'' lo traducen como un anhelo personal fuerte, pero el tema Piel señala una intensidad que va más allá del simple querer, más cercano a saborear o disfrutar plenamente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97629, 'spa', 'Preciosidad, cosas preciadas', 'Preciosidad, valor o cosas atesoradas, ya sean personas u objetos. Daniel es llamado אִישׁ חֲמֻדוֹת (''varón de tesoros''), un término de afecto divino que significa ''grandemente amado'' (Dan 9:23; 10:11, 19). La misma palabra describe bienes materiales valiosos: el botín costoso de 2 Crónicas 20:25 y los tesoros de Egipto en Daniel 11:43.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97633, 'spa', 'Manjares, alimento selecto', 'Alimento selecto o manjares, una aplicación especializada de ''cosas deseables'' al ámbito culinario. Aparece en Daniel 10:3, donde לֶחֶם חֲמֻדוֹת (''pan de cosas deseables'') se refiere a comida rica o selecta a la que Daniel renunció durante su período de duelo de tres semanas. El español ''delicias'' captura bien este matiz gastronómico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97634, 'spa', 'Deleite, cosa deseable', 'Aquello que es deseable, deleitoso o precioso, usado atributivamente para señalar algo especialmente atractivo o codiciado. Amós habla de «viñas de deleite» que los injustos plantaron (Am 5:11), Isaías lamenta los «campos agradables» (Is 32:12), y Ezequiel describe a los oficiales asirios como «jóvenes deseables» para retratar la seducción política de Judá (Ez 23:6, 12, 23).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97637, 'spa', 'Cosa preciosa o valiosa', 'Cosa preciosa o valiosa: objetos concretos atesorados por su valor material o intrínseco. Nabucodonosor se lleva ''vasos preciosos'' del templo (2 Cr 36:10), los pastores de Israel pierden sus ''posesiones preciosas'' bajo juicio (Jer 25:34), y los saqueadores de Nínive se apoderan de sus ''cosas preciosas'' (Nah 2:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97638, 'spa', 'Deleite o agrado', 'Deleite o agrado: la cualidad de ser deleitoso, hermoso o deseable en sí misma. Jeremías llama a su tierra-viña ''mi porción deleitosa'' (chemdati, Jer 12:10), el salmista habla de una ''tierra deseable'' rechazada por Israel (Sal 106:24), y Ezequiel enumera las ''cosas preciosas'' de Tiro entre sus tesoros condenados (Ez 26:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97639, 'spa', 'Deseo o anhelo', 'Deseo o anhelo: la emoción subjetiva de querer o poner el corazón en algo. Samuel pregunta sobre ''todo el deseo de Israel'' (1 Sam 9:20); el rey Joram murió ''sin ser deseado'', es decir, sin ser llorado (2 Cr 21:20); el antagonista de Daniel no hace caso del ''deseo de las mujeres'' (Dan 11:37). Seis apariciones se centran en el acto de desear más que en el objeto deseado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97652, 'spa', 'ira, furor, furia', 'Ira, furor, furia — el sentido dominante con 117 ocurrencias, que describe la cólera intensa en contextos tanto divinos como humanos. La חֵמָה de Dios ''se derrama'' (2 Cr 12:7; 34:25), ''se enciende'' (Sal 89:47) y amenaza con ''consumir'' (Jer 4:4). La חֵמָה humana impulsa la intención homicida de Esaú (Gn 27:44), la rabia de Nabucodonosor (Dn 3:13) y la furia de los malvados (Job 19:29; 36:18). El español ''furor/furia'' y el alemán ''Grimm'' captan la intensidad incandescente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97660, 'spa', 'veneno, ponzoña', 'Veneno, ponzoña — un sentido homónimo que aparece 6 veces, enteramente distinto del significado de ira. En Dt 32:24 Dios envía ''el veneno de los que se arrastran''; en Dt 32:33 el vino de los malvados es ''veneno de serpientes''; en Sal 58:5 los impíos tienen ''veneno como veneno de serpiente.'' El árabe حُمَّى (''ponzoña'') preserva la misma conexión etimológica entre calor y sustancia tóxica. El español ''veneno'' y el francés ''venin'' lo distinguen sin ambigüedad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97694, 'spa', 'calor, fiebre', 'Calor o fiebre — una única ocurrencia en Os 7:5, en la frase חֲמַת מִיָּיִן (''calor/fiebre del vino''), que describe el estado febril y acalorado de la embriaguez entre los líderes corruptos de Israel. BDB clasifica este uso como el significado base literal: calor o fiebre física. El español ''ardor de'' capta directamente el sentido térmico. Esta solitaria ocurrencia preserva el punto de partida etimológico del que derivan tanto la ''furia'' como el ''veneno''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97714, 'spa', 'Sol (poético)', 'El sol como cuerpo celeste, usado como sinónimo poético y profético del término común shemesh. Aparece en contextos escatológicos donde el sol es avergonzado o eclipsado por la gloria de Dios (Is 24:23; 30:26), en la alabanza de la belleza (Cnt 6:10), y en Job 30:28 describiendo ir «sin sol». Todas las lenguas convergen en el referente astronómico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97716, 'spa', 'Calor del sol', 'El calor o la calidez que irradia del sol, centrado en el efecto térmico más que en el cuerpo luminoso. En Sal 19:6, «nada hay que se esconda de su calor», describiendo el alcance penetrante del sol. El vocabulario térmico en español («calor»), francés («chaleur») y alemán («Hitze») confirma esta distinción respecto al sentido celeste.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97719, 'spa', 'Nombre propio femenino', 'Hamutal, nombre propio femenino. Madre de los reyes Joacaz y Sedequías, hija de Jeremías de Libna y esposa de Josías. La forma ketiv חֲמִיטַל podría significar «mi suegro es el rocío», en paralelo con Abital. Sus cinco apariciones en fórmulas de acceso al trono (2 R 23:31; 24:18; Jer 52:1) subrayan su importancia política.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97720, 'spa', 'Nombre propio: Hamul', 'Hamul, hijo de Fares y nieto de Judá. Génesis 46:12 lo incluye entre quienes fueron a Egipto con Jacob. Números 26:21 lo menciona como ancestro del clan hamulita durante el censo en el desierto. 1 Crónicas 2:5 confirma su lugar en la genealogía de Judá. La etimología del nombre (''perdonado'') posiblemente refleja gratitud por la supervivencia o la preservación divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97725, 'spa', 'asno (burro macho)', 'asno (burro macho)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97756, 'spa', 'Hamor', 'El nombre propio Hamor, jefe heveo de Siquem y padre del príncipe Siquem. Figura central en la narrativa de Dina (Gn 34:2-26), donde negocia con los hijos de Jacob tras la agresión de su hijo. También nombrado en Génesis 33:19 como vendedor de la parcela en Siquem, recordado en Josué 24:32 como fuente del terreno de sepultura de Jacob, e invocado en Jueces 9:28 en una apelación a la identidad siquemita.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97758, 'spa', 'Suegra', 'La madre del esposo de una mujer, es decir, su suegra. Predomina en el libro de Rut, donde Noemí es llamada consistentemente חָמוֹת de Rut (Rut 1:14; 2:11, 18-19, 23; 3:1, 6, 16-17), configurando el retrato narrativo de lealtad pactual a través de los vínculos familiares. Miqueas 7:6 emplea el mismo término en una profecía de traición doméstica donde los lazos familiares naturales se desmoronan.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97765, 'spa', 'Quinto (ordinal)', 'Quinto (ordinal): el número ordinal «quinto» que marca posición en una secuencia, atestiguado 34 veces para días (Gn 1:23, el quinto día de la creación), meses (2 R 25:8, el quinto mes), años (Lv 19:25, el quinto año de los frutales), asignaciones tribales (Jos 19:24) y orden de nacimiento (Gn 30:17). Las traducciones emplean el ordinal directo: español «quinto/quinta».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97766, 'spa', 'Una quinta parte (fracción)', 'Una quinta parte (fracción): el sustantivo fraccional «una quinta parte» o «un quinto», que aparece 11 veces en contextos legales y económicos. Se usa para el recargo del veinte por ciento añadido a los pagos de restitución (Lv 5:16; 6:5; 22:14; 27:13-31) y para la tributación de José sobre la producción de Egipto (Gn 47:24). El español distingue del ordinal usando «la quinta parte de».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97776, 'spa', 'Tener compasión, piedad', 'Tener compasión, piedad: aquí la dimensión emocional pasa al primer plano: compasión sentida ante el sufrimiento o la indefensión. Éx 2:6 es paradigmático: la hija de Faraón vio al niño llorando y «tuvo compasión». El español «compadecerse» resalta la identificación empática con el que sufre. En 2 Cr 36:15, 17 la compasión de Dios por su pueblo contrasta marcadamente con la falta de ella por parte de los invasores.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97777, 'spa', 'Perdonar, abstenerse de destruir', 'Perdonar, abstenerse de destruir: el uso más frecuente denota perdonar, abstenerse deliberadamente de un castigo o destrucción que está en el poder de uno. En Dt 13:8 y 1 S 15:3, 9, 15 el contexto es la guerra y el mandato divino: «no perdones». El español «perdonar» capta el matiz jurídico de indultar lo que podría ser destruido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97787, 'spa', 'Preocuparse por, velar por', 'Preocuparse por, velar por: un matiz poco frecuente (Ez 36:21; Zac 11:5) donde el verbo denota preocupación protectora o inversión emocional en el bienestar de algo. En Ez 36:21, Dios «tuvo compasión» de su santo nombre, no piedad hacia alguien que sufre, sino cuidado solícito por algo precioso. El sentido apunta más a resguardar que a simplemente sentir.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97803, 'spa', 'Estar caliente', 'El sentido básico intransitivo del Qal: estar, volverse o ponerse caliente. Abarca la mayoría de las ocurrencias, desde el maná derritiéndose al calentarse el sol (Éx 16:21) hasta el anciano David que no podía entrar en calor (1 R 1:1), y Eliseo acostándose sobre el niño hasta que su carne se calentó (2 R 4:34). En Eclesiastés 4:11 se observa que dos acostados juntos se darán calor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97805, 'spa', 'Calentar transitivamente', 'Piel causativo: calentar, dar calor a otro. Aparece en Job 39:14, donde el avestruz deja sus huevos en la tierra y deja que el polvo los caliente (תְחַמְּמֵם). La negligencia del ave es el punto: la arena, no ella, provee el calor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97810, 'spa', 'Inflamarse figuradamente', 'Nifal reflexivo-figurado: inflamarse, usado en Isaías 57:5 de quienes arden de lujuria entre los robles y bajo todo árbol verde — una imagen de frenesí idolátrico. La calidez de la raíz se convierte en un fuego consumidor e ilícito. La expresión ''los que se encienden'' transmite la intensidad apasionada y autodirigida de este uso raro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97811, 'spa', 'Calentarse reflexivamente', 'Hitpael reflexivo: calentarse deliberadamente. En Job 31:20, Job defiende su cuidado por los pobres, preguntando si el cuerpo del necesitado no se calentó con el vellón de sus ovejas. El tema reflexivo enfatiza la experiencia propia del sujeto al recibir calor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97816, 'spa', 'Pilar solar / incensario', 'Pilares solares o altares de incienso del culto idolátrico, siempre mencionados en contextos de destrucción pagana o juicio profético. Las traducciones oscilan entre «altares de incienso» e «ídolos de sol», reflejando la incertidumbre sobre la forma exacta de estos objetos. Aparecen invariablemente junto a los lugares altos (בָּמוֹת), las aseras y las imágenes talladas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97821, 'spa', 'Ejercer violencia / maltratar', 'Sentido nuclear del Qal activo: cometer violencia, agraviar u oprimir injustamente. Es el corazón ético de la raíz, abarcando violencia tanto física como institucional. Los sacerdotes que «violentan» la Torá (Ez 22:26; Sof 3:4) traicionan la confianza sagrada, mientras los opresores que «roban» y «traman» contra los indefensos (Jer 22:3; Job 21:27) violentan a las personas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97822, 'spa', 'Sacudir / soltar fruto', 'Metáfora botánica especializada: una vid que «sacude» o deja caer su fruto verde (Job 15:33). El sentido diverge marcadamente del de violencia: transmite una expulsión natural más que un agravio interpersonal. Elifaz emplea esta imagen para describir al malvado cuyos proyectos abortan prematuramente, como una vid incapaz de llevar su fruto a madurez.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97824, 'spa', 'Arrancar / derribar', 'Arrancar, desmantelar o destruir por la fuerza. En Lamentaciones 2:6 Dios desgarra su propia morada «como un huerto»: la imagen es impactante. Dios trata su santuario con la misma fuerza destructiva que en otros pasajes se reserva para los enemigos, intensificando la angustia de la destrucción babilónica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97825, 'spa', 'Ser violentado (Nifal)', 'El Nifal pasivo: ser violentado, sufrir violencia. En Jeremías 13:22 las faldas de Jerusalén «son descubiertas» y sus talones «son violentados»; la voz pasiva transfiere el peso de חמס a la víctima. Es el reflejo pasivo del agravio activo del sentido 1, completando el espectro semántico de la raíz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97828, 'spa', 'violencia, brutalidad física', 'violencia, brutalidad física');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97835, 'spa', 'agravio, injusticia, malicia', 'agravio, injusticia, malicia');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97847, 'spa', 'Leudar, fermentar', 'Leudarse o fermentar, dicho de la masa que experimenta el proceso de levadura. Éxodo 12:34 y 12:39 describen la masa de los israelitas que aún no había leudado al partir de Egipto. Oseas 7:4 extiende la metáfora del horneado para retratar la dejadez moral. El Hitpael reflexivo en el Salmo 73:21 interioriza la imagen: el corazón del salmista se amargaba, agriado por la envidia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97850, 'spa', 'Pan con levadura', 'Pan o cualquier alimento preparado con levadura (שְׂאֹר), categóricamente prohibido durante la Pascua y la Fiesta de los Panes sin Levadura. Éxodo 12:15 y 13:3, 7 ordenan su eliminación total de cada hogar durante siete días. La prohibición también rige en los sacrificios: ninguna ofrenda de cereal podía contener levadura (Lv 2:11), y la sangre pascual no debía presentarse junto al chamets (Éx 23:18; 34:25).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97855, 'spa', 'Vinagre, vino agrio', 'Vinagre o vino agrio, un líquido ácido y fermentado. Servía como condimento cotidiano para mojar pan (Rt 2:14), pero estaba prohibido para los nazareos en sus variedades de vino y cerveza (Nm 6:3). Se usa figuradamente para la aspereza: dado al salmista sediento como burla (Sal 69:21) y comparado con la irritación que causa el perezoso (Pr 10:26).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97862, 'spa', 'Espumear o agitarse', 'Espumear, hervir o estar en fermentación, ya sea de líquidos o del cuerpo humano en angustia. En el Salmo 75:8 el vino espumea en la copa del juicio divino, y en el Salmo 46:3 las aguas del mar rugen y se agitan mientras tiemblan los montes. La forma intensiva en Lamentaciones 1:20 y 2:11 aplica la imagen a la angustia visceral: las entrañas del hablante se revuelven ante la calamidad de Jerusalén.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97866, 'spa', 'Vino', 'Vino como bebida fermentada de uva. Las seis apariciones se dividen entre provisiones persas para el templo de Jerusalén (Esd 6:9; 7:22, forma absoluta chamar) y los vasos de vino en el banquete de Belsasar (Dn 5:1, 2, 4, 23, forma enfática chamra). La traducción uniforme en todas las lenguas confirma un sentido único y directo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97868, 'spa', 'Arcilla, barro de alfarero', 'Arcilla, barro de alfarero: tierra moldeable utilizada en alfarería y como metáfora de la humanidad formada por Dios. Los pasajes del alfarero y el barro en Isaías (Is 29:16; 45:9; 64:8) constituyen el corazón teológico, mientras Job reflexiona sobre ser formado del barro (Job 10:9) y habitar en ''casas de barro'' (Job 4:19).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97870, 'spa', 'Mortero, cemento de construcción', 'Mortero, cemento de construcción: material práctico que une ladrillos entre sí. En Babel los constructores dicen ''usemos betún por mortero'' (Gn 11:3); en Egipto los israelitas sufren ''con mortero y ladrillo'' (Éx 1:14); Nahúm ordena a la sitiada Nínive ''pisar el mortero'' para reparar sus muros (Nah 3:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97871, 'spa', 'Lodo, fango', 'Lodo, fango: tierra húmeda y sucia que se encuentra en las calles o lugares bajos, con connotaciones de contaminación y humillación. Isaías describe a Asiria pisoteando naciones como ''el lodo de las calles'' (Is 10:6), y Job dice que Dios lo ha ''arrojado al lodo'' para expresar su degradación (Job 30:19).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97879, 'spa', 'Montón o pila', 'Montón o pila acumulada. Éxodo 8:14 (hebreo 8:10) describe a los egipcios juntando ranas muertas ''en montones y montones'' (reduplicación enfática), creando un hedor por toda la tierra. Habacuc 3:15 contiene la frase oscura ''montón de grandes aguas'', que probablemente representa la procesión triunfal de Dios a través de mares caóticos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97880, 'spa', 'Homer (medida de áridos)', 'El homer, la mayor medida estándar de áridos en el antiguo Israel, equivalente a diez efas (aproximadamente 220 litros). Se usaba para medir grano, cebada y semilla en contextos comerciales, cultuales y legales. Ezequiel 45:11 lo define explícitamente en relación con el efa y el bato. Levítico 27:16 establece el precio de la tierra según el homer de cebada necesario para sembrarla.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97883, 'spa', 'Barro / argamasa', 'Barro o argamasa como sustancia material, probablemente de una raíz homónima. En Isaías 41:25 el conquistador viene sobre los gobernantes «como el alfarero» pisa el חֹמֶר — aquí refiriéndose inequívocamente al barro, no a una unidad de volumen. Algunos léxicos lo tratan como un lema distinto (ḥōmer II), pero la forma consonántica es idéntica y solo el contexto permite la diferenciación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97886, 'spa', 'Betún o asfalto', 'Betún o asfalto usado en construcción e impermeabilización. Génesis 11:3 relata que los constructores usaron betún en lugar de argamasa para la torre de Babel. Génesis 14:10 señala que el valle de Sidim tenía pozos de asfalto, creando peligros durante la batalla. Éxodo 2:3 describe cómo la madre de Moisés recubrió su canasta ''con betún y brea'' para impermeabilizarla.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97890, 'spa', 'cardinal: cinco', 'El numeral cardinal ''cinco'' usado de forma independiente o en estado constructo para denotar la cantidad cinco. Con 309 ocurrencias es el uso primario, desde las genealogías de Génesis 5 (''Enós vivió cinco años'', Gn 5:6) hasta las medidas del tabernáculo y del templo. Todas las lenguas meta lo traducen uniformemente — español ''cinco'', francés ''cinq'', alemán ''fünf'' — confirmando una equivalencia numérica inequívoca.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97892, 'spa', 'compuesto: quince', 'El numeral ''cinco'' como componente del número compuesto quince (חֲמֵשׁ עֶשְׂרֵה, ''cinco-y-diez''). Con 22 ocurrencias, esta formación es propia de los numerales compuestos hebreos. Figura destacadamente en medidas: ''las aguas prevalecieron quince codos hacia arriba'' (Gn 7:20) y en las dimensiones de las cortinas del tabernáculo (Éx 27:14-15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97895, 'spa', 'ordinal: quinto', 'El numeral con valor ordinal significando ''el quinto'', marcando un día, mes o año específico. Seis ocurrencias anclan la cronología profética (Ez 1:1, ''en el quinto año''; Ez 8:1, ''en el quinto día del sexto mes'') y la historia real (1 R 12:32-33, la fiesta de Jeroboam). Las glosas revelan el reto de convertir un cardinal en ordinal en distintas lenguas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97896, 'spa', 'ordinal: decimoquinto', 'El numeral en construcciones compuestas-ordinales con el significado de ''el decimoquinto'', especialmente en fórmulas de datación litúrgica. Ocho ocurrencias fijan fechas del calendario sagrado: ''el día quince del segundo mes'' (Éx 16:1), la Fiesta de los Panes sin Levadura (Lv 23:6; Nm 28:17) y la Fiesta de los Tabernáculos (Nm 29:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97916, 'spa', 'Vientre o abdomen', 'El vientre o abdomen, la zona vulnerable de la parte media del torso. Todas las apariciones se dan en contextos de asesinato por apuñalamiento en 2 Samuel: Abner clava su lanza hacia atrás en el vientre de Asael (2:23), Joab hiere a Abner en el abdomen como venganza (3:27), los asesinos de Is-boset lo golpean allí (4:6) y Joab mata a Amasa con un golpe en el vientre (20:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97917, 'spa', 'Armado en formación', 'Equipado en orden de batalla, armado y organizado para la acción militar. En Éxodo 13:18 los israelitas salen de Egipto en filas ordenadas, no como turba desorganizada. Josué 1:14 y 4:12 describen a las tribus transjordanas cruzando el Jordán armadas delante de sus hermanos. Jueces 7:11 emplea el término para el límite del campamento armado al que se acercó Gedeón.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97918, 'spa', 'cincuenta (cardinal)', 'El número cardinal cincuenta, empleado para contar cantidades: medidas, edades, precios, duraciones y enumeraciones. Cubre la gran mayoría de las ocurrencias (151×). Gn 6:15 indica que el arca mide cincuenta codos de ancho; Gn 18:24 pregunta si Dios perdonará la ciudad por cincuenta justos. Las traducciones convergen de manera uniforme: spa cincuenta, fra cinquante, deu fünfzig.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97921, 'spa', 'grupo de cincuenta', 'Una unidad militar u organizativa de cincuenta hombres, frecuente en la construcción «jefe de cincuenta» (שַׂר חֲמִשִּׁים) o con sufijos posesivos («sus cincuenta», «tus cincuenta») que designan a los soldados bajo un comandante. Éx 18:21, 25 y Dt 1:15 establecen la jerarquía administrativa: jefes de miles, de cientos, de cincuenta y de diez. En 2 Re 1:9-14 Ocozías envía «un capitán de cincuenta con sus cincuenta» contra Elías.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97932, 'spa', 'Odre de agua', 'Un odre o recipiente de cuero usado para llevar agua. Las tres apariciones seguras se encuentran en Génesis 21, el relato de la expulsión de Agar: Abraham coloca un odre de agua sobre su hombro (21:14), el agua del odre se acaba (21:15) y Dios provee un pozo para que ella lo llene de nuevo (21:19). La cuarta referencia (Hab 2:15) es textualmente incierta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97933, 'spa', 'Hamat (ciudad y región)', 'Hamat (ciudad y región): el nombre propio Hamat, que designa la ciudad-estado siria sobre el río Orontes que servía como marcador convencional del límite norte del territorio israelita. La frase estereotipada «la entrada de Hamat» aparece en las descripciones de fronteras desde Números hasta Ezequiel (Nm 13:21; 34:8; Jos 13:5; 1 R 8:65; 2 R 14:25; Ez 47:16, 20). Históricamente, su rey Toi se alió con David contra Hadad-ezer (2 S 8:9-10), y sus dioses fueron llevados a Samaria por colonos asirios (2 R 17:30).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97943, 'spa', 'favor, buena voluntad', 'favor, buena voluntad');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97944, 'spa', 'gracia, encanto, elegancia', 'gracia, encanto, elegancia');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97951, 'spa', 'Patriarca levita', 'Patriarca levita cuya familia contribuyó a las obras de reconstrucción postexílica. Sus hijos supervisaron la edificación del templo en Esdras 3:9, repararon las murallas bajo Nehemías (Neh 3:18, 24) y sellaron el pacto en Nehemías 10:9. El nombre combina la palabra hebrea para gracia o favor con el nombre divino Hadad, deidad semítica noroccidental de la tormenta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97952, 'spa', 'acampar, plantar campamento', 'Establecer un campamento, plantar tiendas o asentarse temporalmente durante un viaje, migración o peregrinación por el desierto. Es el sentido abrumadoramente dominante (130 de 143 ocurrencias), columna vertebral de los itinerarios en Números 33. Las glosas interlingüísticas convergen: spa acamparon, fra campèrent, deu lagerten. Pasajes clave incluyen la partida del Éxodo (Éx 13:20) y la llegada al Sinaí.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97957, 'spa', 'acampar contra, asediar', 'Establecer un campamento militar contra una ciudad o enemigo, implicando asedio o intención hostil. El mismo acto físico de plantar campamento adquiere fuerza agresiva cuando se dirige contra un objetivo. Pasajes centrales incluyen a Najas sitiando Jabes de Galaad (1 S 11:1), la orden de David de sitiar Rabá (2 S 12:28) y los oráculos proféticos donde Dios acampa contra Jerusalén (Is 29:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97991, 'spa', 'Ana (nombre propio)', 'El nombre propio Ana (חַנָּה), madre del profeta Samuel, atestiguado exclusivamente en 1 Samuel 1-2. Su narrativa sigue un arco completo: esterilidad y aflicción (1:2-8), oración ferviente confundida con embriaguez (1:9-15), el voto y su cumplimiento (1:19-28), y su salmo de acción de gracias (2:1-10). El nombre deriva de la raíz חנן (''ser clemente''), vinculado temáticamente a la gracia que ella recibió.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97994, 'spa', 'Enoc (hijo de Caín / hijo de Jared)', 'Enoc (hijo de Caín / hijo de Jared): se refiere principalmente al hijo de Jared en la genealogía de Set, el justo que caminó con Dios y fue arrebatado sin morir (Gn 5:18-24; 1 Cr 1:3). También se aplica al hijo de Caín, en cuyo honor se nombró la primera ciudad (Gn 4:17-18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97995, 'spa', 'Hanoc (hijo de Rubén / hijo de Madián)', 'Hanoc (hijo de Rubén / hijo de Madián): el mismo nombre hebreo חֲנוֹךְ pero transliterado convencionalmente de forma diferente para distinguir a dos portadores menos conocidos: un hijo de Madián y nieto de Abraham por Cetura (Gn 25:4; 1 Cr 1:33), y un hijo de Rubén, ancestro del clan hanoquita (Gn 46:9; Éx 6:14; Nm 26:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (97999, 'spa', 'Hanún (nombre propio)', 'Hanún hijo de Nahas, rey de Amón, quien sucedió a su padre y ultrajó a los enviados de David que traían condolencias (2 S 10:1-4; 1 Cr 19:2-6). Su provocación desencadenó una importante campaña militar en la que Amón y sus aliados arameos fueron derrotados de manera decisiva. La narrativa ilustra cómo una afrenta diplomática puede escalar hasta convertirse en una guerra a gran escala.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98002, 'spa', 'Clemente, compasivo', 'Atributo divino que significa clemente o compasivo, usado exclusivamente de Dios y casi siempre emparejado con רַחוּם (''misericordioso'') en la fórmula litúrgica que se origina en Éxodo 34:6. Atestiguado en el código del pacto (Éx 22:27), la teofanía del Sinaí (Éx 34:6), la alabanza sálmica (Sal 86:15; 103:8; 111:4; 112:4; 116:5; 145:8), las apelaciones proféticas (Jl 2:13; Jon 4:2) y la narrativa postexílica (2 Cr 30:9; Neh 9:17, 31).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98009, 'spa', 'Embalsamar o madurar', 'Embalsamar un cadáver con especias aromáticas según la costumbre funeraria egipcia. Génesis 50:2 registra que José mandó a los médicos embalsamar a Jacob, y Génesis 50:26 menciona el embalsamamiento del propio José. La misma raíz aparece en Cantares 2:13, donde la higuera madura o sazona sus primeros frutos, vinculando la idea de especias con la fragancia natural de la maduración.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98015, 'spa', 'lanza, pica', 'lanza, pica');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98030, 'spa', 'Dedicar, inaugurar', 'Dedicar, inaugurar una estructura para su uso sagrado o doméstico. Se aplica a la dedicación del templo de Salomón (1 R 8:63; 2 Cr 7:5) y a una casa recién construida (Dt 20:5). El cognado árabe حنك («frotar el paladar de un recién nacido») apunta a un significado iniciático: preparar algo para su primer uso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98031, 'spa', 'Dedicación ceremonial', 'Ceremonia formal de dedicación o consagración, especialmente de una estructura sagrada o monumental. Esdras 6:16-17 describe la gozosa dedicación del Segundo Templo, donde los exiliados retornados ofrecen sacrificios y organizan las divisiones sacerdotales. Daniel 3:2-3 emplea el mismo término para la dedicación de la imagen de oro de Nabucodonosor en la llanura de Dura. La palabra conlleva un peso ceremonial significativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98032, 'spa', 'Dedicación, consagración ceremonial', 'Ceremonia de dedicación o consagración de una estructura sagrada —altar, templo o muralla— que la aparta para el servicio divino. Aparece en dos contextos principales: la dedicación del altar del tabernáculo con su secuencia de ofrendas tribales durante doce días (Números 7), y las dedicaciones del templo salomónico y las murallas de Nehemías, marcadas por sacrificio, música y gozo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98038, 'spa', 'Sin causa, inmerecidamente', 'Sin causa, inmerecidamente: describe una acción realizada sin justificación ni causa legítima, una hostilidad o acusación injusta e inmerecida. Los Salmos están llenos de este uso: los enemigos de David lo odian «sin causa» (Sal 35:7, 19; 69:4), y Job insiste en que Dios lo ha afligido sin motivo (Job 2:3; 9:17). Es el sentido más frecuente del término.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98039, 'spa', 'Gratuitamente, sin costo', 'Gratuitamente, sin costo: denota algo dado, recibido o realizado sin pago, gratis, sin costo alguno. Labán pregunta a Jacob si debería servir «de balde» solo por ser familia (Gn 29:15), y el esclavo liberado sale sin rescate (Éx 21:2, 11). El español usa tanto «de balde» como «de gracia», este último preservando bellamente el vínculo etimológico con חֵן.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98040, 'spa', 'En vano, sin propósito', 'En vano, sin propósito: expresa futilidad o falta de propósito. Cuando la red se tiende en vano ante los ojos del ave (Pr 1:17), la acción no logra nada. Ezequiel lo usa para advertir que los juicios de Dios no son en vano, no son vacíos ni carentes de propósito (Ez 6:10; 14:23). Se solapa con «sin causa» pero enfatiza el resultado más que la justificación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98043, 'spa', 'Inocencia, inculpabilidad', 'Inocencia, inculpabilidad: usado como sustantivo en 1 R 2:31 para denotar el estado de inocencia o inculpabilidad: la «sangre inocente» derramada sin justa causa. Aquí la palabra funciona como sustantivo y no como adverbio, describiendo no la manera de una acción sino el estatus moral de una persona. Este raro uso sustantival conecta los sentidos de «sin causa» y «gratuitamente» en un concepto jurídico-moral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98048, 'spa', 'Nombre propio', 'Nombre personal del primo de Jeremías, hijo de su tío Salum. Las cuatro apariciones se concentran en Jeremías 32:7-12, donde Hanamel acude al profeta encarcelado pidiéndole que ejerza su derecho de redención (גְּאֻלָּה) sobre un campo en Anatot. El nombre es un compuesto teofórico que significa «Dios es misericordioso».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98050, 'spa', 'ser clemente, mostrar favor (Qal)', 'ser clemente, mostrar favor (Qal)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98052, 'spa', 'implorar favor, suplicar (Hitpael)', 'implorar favor, suplicar (Hitpael)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98061, 'spa', 'hacer agradable o placentero', 'hacer agradable o placentero');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98062, 'spa', 'recibir favor (Hofal pasivo)', 'recibir favor (Hofal pasivo)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98076, 'spa', 'mostrar compasión, tener piedad (Piel intensivo)', 'mostrar compasión, tener piedad (Piel intensivo)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98082, 'spa', 'gemir (forma disputada)', 'gemir (forma disputada)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98107, 'spa', 'Hanán (nombre propio)', 'El nombre propio Hanán (de janán, «clemente»), portado por al menos ocho individuos distintos en Crónicas, Esdras-Nehemías y Jeremías, incluyendo benjaminitas, guerreros de David, sirvientes del templo, levitas auxiliares y un propietario de una cámara del templo. La variante conjuntiva «y Hanán» es sintáctica, no semántica. La transliteración es uniforme en todas las lenguas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98110, 'spa', 'Torre de Jerusalén', 'Torre (מִגְדָּל) situada en la muralla norte de Jerusalén, que servía como punto de referencia en las descripciones del perímetro de la ciudad. En el relato de la reconstrucción de Nehemías (Neh 3:1; 12:39) es consagrada junto a la Puerta de las Ovejas, mientras que en las visiones proféticas (Jer 31:38; Zac 14:10) marca el límite de la ciudad restaurada o transformada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98111, 'spa', 'Hanani (nombre propio)', 'Hanani el vidente, padre del profeta Jehú. Confrontó al rey Asá de Judá por su alianza con Ben-hadad de Aram y fue encarcelado (2 Cr 16:7-10). Su ministerio profético enfatizaba la confianza en el SEÑOR por encima de las alianzas políticas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98113, 'spa', 'Un nombre personal teofórico que significa ''YHWH ha sido clemente'', llevado por ', 'Un nombre personal teofórico que significa ''YHWH ha sido clemente'', llevado por múltiples individuos distintos a lo largo de la Biblia hebrea. Los más prominentes incluyen al compañero de Daniel renombrado Sadrac (Dn 1:6-7, 19), el falso profeta que se enfrentó a Jeremías rompiendo las barras del yugo (Jer 28:1-17), un hijo de Zorobabel en la línea davídica (1 Cr 3:19, 21) y un capitán militar bajo Uzías (2 Cr 26:11). La frecuencia del nombre atestigua la popularidad de los nombres de acción de gracias entre los judíos postexílicos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98120, 'spa', 'Ser profanado o contaminado', 'Qal: volverse contaminado, profanado o impuro, describiendo un estado de contaminación moral o ritual que recae sobre una tierra o un pueblo. El Salmo 106:38 dice que la tierra ''fue contaminada'' (vatechnaf) con sangre inocente; Isaías 24:5 declara la tierra profanada bajo sus habitantes por violar el pacto eterno. Jeremías 3:1 y 3:9 lo aplican a la tierra mancillada por la adulterio espiritual de Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98123, 'spa', 'Corromper con adulación', 'Hifil en sentido social-moral: corromper o desviar mediante adulación, palabras lisonjeras o hipocresía. Daniel 11:32 profetiza que el rey del norte ''seducirá con lisonjas'' a quienes violan el pacto, subrayando la dimensión engañosa y relacional. Este sentido preserva la idea raíz de ''inclinarse lejos de lo recto'' trasladándola al ámbito de la manipulación interpersonal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98127, 'spa', 'Causar contaminación', 'Hifil causativo: profanar, contaminar o hacer impuro algo mediante las propias acciones. Números 35:33 emplea dos veces esta forma: ''la sangre contamina la tierra'' y ''no contaminaréis la tierra'', estableciendo el principio de que el homicidio sin expiar corrompe el territorio. Jeremías 3:2 extiende esto a la idolatría de Judá que profana el paisaje.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98131, 'spa', 'Impío, profano, hipócrita', 'Persona profana, impía o hipócrita cuya pretensión religiosa oculta bancarrota moral. Predominante en Job (8:13; 13:16; 15:34; 17:8; 20:5; 27:8; 34:30; 36:13), donde caracteriza a quienes cuya piedad es superficial y cuyo fin es la ruina. También se aplica a naciones (Is 9:16; 10:6) y grupos (Is 33:14; Sal 35:16). El cognado árabe paradójicamente significa ''devoto'', destacando una notable divergencia semántica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98144, 'spa', 'fidelidad pactual, amor leal', 'El sentido teológico dominante: el amor fiel, arraigado en el pacto, que Dios mantiene hacia su pueblo (167 de 249 ocurrencias). Es el חֶסֶד del gran estribillo de los Salmos כִּי לְעוֹלָם חַסְדּוֹ («porque para siempre es su misericordia», Sal 136). Combina lealtad, amor y confiabilidad de un modo que ningún vocablo aislado logra captar. Español misericordia, alemán Gnade y francés bonté capturan cada uno una faceta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98145, 'spa', 'bondad, benevolencia', 'Bondad y benevolencia interpersonal entre seres humanos (53 ocurrencias), concentrada en Génesis y los libros narrativos. Abraham pide a Abimelec que «haga bondad» (Gn 20:13); los espías prometen a Rajab חֶסֶד (Jos 2:12). Aquí domina la dimensión relacional y horizontal sobre la vertical o divina. El árabe iḥsān y el suajili wema seleccionan esta beneficencia entre personas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98159, 'spa', 'devoción, lealtad', 'Devoción humana y lealtad pactual entre personas (5 ocurrencias), con énfasis en la fidelidad y el compromiso firme en relaciones personales. El חֶסֶד de Rut hacia Noemí (Rt 3:10), la súplica de Jonatán a David (1 S 20:15) y el nostálgico «el חֶסֶד de tu juventud» de Jeremías (Jer 2:2) se centran en la lealtad jurada entre personas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98161, 'spa', 'actos leales, fidelidades', 'Actos concretos y plurales de fidelidad pactual (15 ocurrencias), siempre en las formas plurales חֲסָדִים o constructas חַסְדֵי. Jacob reconoce los חֲסָדִים específicos de Dios (Gn 32:11); Isaías habla de חַסְדֵי דָוִד, las «misericordias firmes de David» (Is 55:3). El paso de la cualidad abstracta a actos históricos contables se confirma por los plurales en árabe y coreano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98167, 'spa', 'misericordia, compasión', 'La dimensión compasiva y misericordiosa de חֶסֶד (7 ocurrencias), donde el contexto pone en primer plano la ternura y la piedad hacia quienes sufren. En 1 Re 20:31 los arameos apelan a los reyes de Israel como «reyes misericordiosos»; en Lm 3:32 el חֶסֶד de Dios sigue a su aflicción. Francés miséricorde y árabe raḥma afloran aquí en vez del vocabulario de lealtad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98217, 'spa', 'favor, gracia', 'Beneplácito o gracia (solo 2 ocurrencias), ambas en contextos cortesanos de la diáspora. Ester halla חֶסֶד ante el oficial del rey (Est 2:9); Daniel halla חֶסֶד ante su supervisor babilonio (Dn 1:9). El contexto se acerca más a «favor» o «gracia» que al amor pactual; el árabe ḥuẓwa/niʿma y el suajili neema confirman este sentido periférico distintivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98236, 'spa', 'Refugiarse, buscar amparo', 'Refugiarse, buscar amparo: buscar refugio o cobijo, expresando confianza y dependencia al huir hacia un protector. Casi todas las apariciones describen el acto de buscar protección divina, con Dios retratado como fortaleza, roca o ave que cobija. La forma participial חֹסִים (''los que se refugian'') funciona como título virtual de los fieles (Sal 2:12; 5:12; 17:7; 34:9; Nah 1:7). Rut 2:12 capta esto hermosamente cuando Booz bendice a Rut por haber venido «a refugiarse bajo las alas del Dios de Israel». El único uso negativo aparece en Dt 32:37, donde se reprocha a Israel por haberse refugiado en dioses falsos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98258, 'spa', 'Nombre propio dual', 'Hosa, nombre propio que significa «refugio». Designa a (a) un levita merarita portero bajo David, asignado a la puerta occidental de Salequet (1 Cr 16:38; 26:10, 11, 16), y (b) una ciudad fronteriza en el territorio de Aser (Jos 19:29) cuyo sitio es desconocido. La Septuaginta diverge notablemente (Ἰασίφ, Σουσά, Ὠσά).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98260, 'spa', 'Fieles / santos (comunidad)', 'Fieles / santos (comunidad): los fieles o santos como comunidad, el cuerpo colectivo del pueblo del pacto de Dios, siempre en plural y típicamente con sufijos posesivos («sus fieles», «tus santos»). Sal 37:28 promete que el SENOR «no abandona a sus fieles»; Sal 149:1 llama a los חֲסִידִים a cantar un cántico nuevo; y 1 S 2:9 declara que «guardará los pies de sus fieles».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98261, 'spa', 'Fiel / piadoso (individuo)', 'Fiel / piadoso (individuo): un solo individuo piadoso o fiel, el adjetivo sustantivado usado de una persona que encarna la lealtad de pacto y la piedad ante Dios. A David se le llama חָסִיד de Dios en Sal 89:19; el salmista apela a su propia condición de חָסִיד en Sal 86:2; y 2 S 22:26 describe el principio de reciprocidad: «con el fiel te muestras fiel». Dt 33:8 aplica el término a la tribu de Leví.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98271, 'spa', 'Misericordioso / clemente (atributo divino)', 'Misericordioso / clemente (atributo divino): un atributo divino aplicado a Dios mismo y no a seres humanos. Sal 145:17 declara que «el SENOR es justo en todos sus caminos y חָסִיד en todas sus obras», y Jer 3:12 tiene a Dios diciendo «yo soy חָסִיד». Aquí el adjetivo asciende desde describir al practicante humano de חֶסֶד hasta su fuente última.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98286, 'spa', 'La cigüeña', 'La cigüeña, ave zancuda migratoria grande clasificada como ritualmente impura (Lev 11:19; Deut 14:18). La asociación del ave con la devoción parental (de la raíz ch-s-d, ''lealtad'') agudiza la ironía de Jeremías: incluso la cigüeña conoce sus estaciones, pero el pueblo de Dios no conoce sus ordenanzas (Jer 8:7). En Sal 104:17 habita en los cipreses.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98290, 'spa', 'Langosta destructora', 'Una especie o etapa destructiva de langosta que aparece siempre como agente de devastación de cultivos. El término se presenta invariablemente en paralelo con otros vocablos para langosta: arbeh y yeleq en Joel 1:4; 2:25, y arbeh solo en 1 R 8:37 y Sal 78:46. Isaías 33:4 lo emplea como imagen de saqueo voraz e irresistible.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98303, 'spa', 'riqueza y tesoro', 'Riqueza, tesoro, bienes acumulados. Designa la abundancia material poseida por individuos (Pr 15:6, emparejado con ''grande''; Pr 27:24, en paralelo con ''corona'') o ciudades (Jer 20:5, el tesoro de Jerusalen, junto a ''trabajo'' y ''cosas preciosas''). Ezequiel 22:25 lo vincula con riquezas obtenidas mediante violencia. Isaias 33:6 lo extiende figuradamente a la provision divina: ''riqueza de salvaciones, sabiduria y conocimiento.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98305, 'spa', 'Barro, arcilla cerámica', 'Barro o material cerámico que designa específicamente la sustancia de alfarería que forma parte de los pies compuestos de la estatua soñada por Nabucodonosor. Las nueve ocurrencias se concentran en Daniel 2:33-45, donde el barro se contrasta con el hierro para simbolizar un reino parcialmente fuerte y parcialmente frágil, incapaz de cohesión duradera.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98309, 'spa', 'El sentido Qal fundamental', 'El sentido Qal fundamental: carecer, estar en necesidad, estar sin algo. Abarca tanto la necesidad material (Dt 15:8, ''todo lo que le falte'') como la seguridad existencial (Sal 23:1, el sustantivo relacionado). Deuteronomio 2:7 y Nehemías 9:21 lo emplean en la retrospectiva del desierto de Israel — ''nada te ha faltado'' — mientras Proverbios 31:11 lo aplica al hogar de la mujer virtuosa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98311, 'spa', 'El sentido causativo Hifil', 'El sentido causativo Hifil: hacer que falte o privar. En Éxodo 16:18 el milagro del maná se describe de modo que quien recogió poco ''no le faltó'', donde el Hifil implica la provisión divina que previene el déficit. Isaías 32:6 lo usa para los malvados que niegan la bebida al sediento. El español ''hacer faltar'' y las formas francesas con matiz causativo captan la privación dirigida por un agente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98313, 'spa', 'El sentido Qal de disminución o reducción física, aplicado a fenómenos naturales', 'El sentido Qal de disminución o reducción física, aplicado a fenómenos naturales. Génesis 8:3 y 8:5 describen las aguas del diluvio ''disminuyendo'' y ''menguando continuamente''. El español ''disminuir'' y el alemán ''abnehmen'' (menguar) lo traducen como una reducción gradual y mensurable en cantidad, distinta de la necesidad personal o la privación moral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98316, 'spa', 'El sentido intensivo-causativo Piel', 'El sentido intensivo-causativo Piel: hacer inferior o privar activamente a alguien. El Salmo 8:5 declara célebremente que Dios hizo al ser humano ''un poco menor que los seres celestiales'', usando esta conjugación para expresar un posicionamiento deliberado en la jerarquía cósmica. Eclesiastés 4:8 lo aplica a la autoprivación, privando al alma de lo bueno.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98329, 'spa', 'Falto, carente', 'Falto, carente: adjetivo que describe a quien es deficiente, necesitado o privado de algo, generalmente en estado constructo con aquello de lo que carece. El patrón bíblico dominante es חֲסַר־לֵב (''falto de corazón/juicio''), que aparece repetidamente en Proverbios (6:32; 7:7; 9:4, 16; 10:13; 11:12; 12:11; 15:21; 17:18; 24:30) para denotar ceguera moral insensata.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98339, 'spa', 'Carencia total', 'Falta completa de necesidades básicas. Deuteronomio 28:48, 57 describe condiciones de asedio con ''carencia de todo'', incluyendo alimentos y provisiones esenciales, que empujan a la gente al canibalismo. Amós 4:6 emplea el eufemismo ''falta de pan'' (literalmente ''limpieza de dientes'') para describir la hambruna que Dios envió como llamado de atención.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98344, 'spa', 'Revestir o recubrir', 'Revestir o recubrir una superficie con un material, usado exclusivamente en el Piel para la construcción del templo. El Cronista describe cómo Salomón revistió (wayeḥap) la sala principal con ciprés y luego con oro fino (2 Cr 3:5), y de manera similar el santuario interior, vigas, umbrales, paredes y puertas (2 Cr 3:7-9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98346, 'spa', 'Cubrir o ser cubierto', 'Cubrir o ser cubierto, especialmente cubrirse la cabeza como señal de duelo, luto, vergüenza o condena. En el Qal, la cabeza (rōʾš) es el objeto típico: David y sus seguidores se cubren la cabeza al huir de Absalón (2 S 15:30), y Jeremías describe a los agricultores con la cabeza cubierta durante la sequía (Jer 14:3-4). Ester 6:12 y 7:8 usan el participio ḥăpūy rōʾš para la desgracia de Amán.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98354, 'spa', 'Dosel o cámara nupcial', 'Dosel o cámara nupcial que provee cobertura y recinto. Salmo 19:5 compara al sol emergente con un novio que sale ''de su cámara'', irradiando gozo y fuerza. Isaías 4:5 promete que sobre la gloria de Sion habrá ''un dosel'' de protección. Joel 2:16 convoca incluso a la novia ''de su dosel'' para participar en el arrepentimiento nacional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98356, 'spa', 'Apresurarse, darse prisa', 'Apresurarse, darse prisa, ir con urgencia, un movimiento rápido general sin implicar necesariamente miedo. Abarca la huida apresurada de la nodriza con el joven Mefiboset (2 S 4:4), la urgencia de David por escapar de Saúl (1 S 23:26), la retirada precipitada del ejército arameo dejando vestiduras por el camino (2 R 7:15) y la instrucción de no ''apresurarse'' por temor en batalla (Dt 20:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98358, 'spa', 'Huir con alarma o pánico', 'Estar alarmado, huir presa del pánico, sobresaltarse, enfatizando el componente emocional del miedo y la agitación. El ''en mi angustia'' del salmista (bechofzi, Sal 31:23; 116:11) expresa un temor repentino y desorientador. El Salmo 48:5 describe a reyes hostiles que vieron a Sion y ''se turbaron, huyeron despavoridos'' (Nifal), mientras que Sal 104:7 retrata las aguas primordiales huyendo ante la voz atronadora de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98366, 'spa', 'Prisa bajo presión', 'Prisa o huida apresurada, generalmente bajo coacción. Éxodo 12:11 ordena comer la Pascua «con prisa», listos para partir de inmediato de Egipto. Deuteronomio 16:3 identifica el pan sin levadura como «pan de aflicción» porque salieron de Egipto «con prisa», sin tiempo para que la masa leudara. Isaías 52:12 promete lo contrario para el futuro: «no saldréis con prisa», sino con dignidad y protección divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98367, 'spa', 'Nombre propio benjaminita', 'Nombre personal benjaminita con importancia genealógica. Génesis 46:21 enumera a Hupim entre los hijos de Benjamín que fueron a Egipto. 1 Crónicas 7:12, 15 incluye referencias a Hupim (y la variante Hufam) en genealogías benjaminitas complejas con dificultades textuales. Las variaciones preposicionales reflejan la integración del nombre en distintos enunciados genealógicos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98368, 'spa', 'Hueco de las manos', 'La concavidad formada por dos manos ahuecadas juntas, siempre en forma dual (chophnayim), usada como medida o recipiente para asir y sostener material. En Ex 9:8 contiene hollín de horno; en Lev 16:12 brasas de incienso ardiente; en Prov 30:4 es un recipiente imposible para el viento; en Ecl 4:6 mide el contraste entre sosiego y afán vano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98374, 'spa', 'nombre propio masculino', 'Jofni, nombre propio masculino. Uno de los dos hijos sacerdotes de Eli en Silo, siempre mencionado junto a su hermano Finees. Sus cinco apariciones se concentran en 1 Samuel 1-4, enmarcando la narrativa de corrupcion sacerdotal y retribucion divina: la mencion inicial en el santuario de Silo (1:3), el oraculo de muerte (2:34) y el cumplimiento catastrofico en Afec (4:4, 11, 17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98376, 'spa', 'deleitarse en, complacerse en', 'deleitarse en, complacerse en');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98378, 'spa', 'desear, querer, estar dispuesto', 'desear, querer, estar dispuesto');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98430, 'spa', 'Que se deleita, deseoso', 'Que se deleita en algo, que se complace en ello, describiendo a una persona cuyo corazón se siente atraído hacia algo bueno o digno. Dios no es quien ''se deleita'' en la maldad (Sal 5:5), la persona piadosa ''se deleita en la vida'' (Sal 34:13), y los partidarios del SEÑOR ''se complacen en'' la justicia de su siervo (Sal 35:27). David encarga a Salomón servir a Dios con un corazón ''dispuesto'' (1 Cr 28:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98439, 'spa', 'deleite, placer', 'deleite, placer');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98441, 'spa', 'asunto, negocio', 'asunto, negocio');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98442, 'spa', 'deseo, voluntad', 'deseo, voluntad');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98448, 'spa', 'cosa preciosa o deseable', 'cosa preciosa o deseable');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98468, 'spa', 'Nombre personal y simbólico', 'Tanto el nombre histórico de la madre del rey Manasés (2 Re 21:1) como un nombre profético simbólico para la Jerusalén restaurada (Is 62:4). El pasaje de Isaías etimologiza explícitamente el nombre: כִּי־חָפֵץ יְהוָה בָּךְ («porque el SEÑOR se deleita en ti»), contrastándolo con עֲזוּבָה (Desamparada) y שְׁמָמָה (Desolada). Los traductores oscilan entre transliterar y traducir el sentido del nombre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98469, 'spa', 'Cavar o excavar físicamente el suelo, especialmente la perforación de pozos y la', 'Cavar o excavar físicamente el suelo, especialmente la perforación de pozos y la apertura de fosas. Este es el sentido primario y concreto, atestiguado desde las narraciones patriarcales en adelante. En Génesis 26:15-22 Isaac vuelve a cavar los pozos de su padre Abraham, y Eclesiastés 10:8 advierte que quien cava una fosa puede caer en ella. El español ''cavaron'' y el alemán ''graben'' traducen sistemáticamente esta acción literal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98471, 'spa', 'Explorar, espiar o reconocer una región, extendiendo la metáfora de ''cavar'' a un', 'Explorar, espiar o reconocer una región, extendiendo la metáfora de ''cavar'' a una investigación minuciosa. Cuando Moisés envía exploradores en Deuteronomio 1:22, el verbo transmite un reconocimiento profundo. Josué 2:2-3 usa el mismo sentido para los espías en Jericó. El francés ''chercher'' y el español ''espiar'' en estos pasajes resaltan el matiz investigativo que distingue este sentido de la mera excavación física.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98483, 'spa', 'Buscar algo con intensa avidez, como quien excava en busca de un tesoro escondid', 'Buscar algo con intensa avidez, como quien excava en busca de un tesoro escondido. Esta cumbre metafórica aparece en Job 3:21, donde el sufriente describe a quienes anhelan la muerte y ''la cavan'' más que a riquezas ocultas. La única aparición conserva una vívida extensión poética: un deseo tan desesperado que refleja el sudor de la excavación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98485, 'spa', 'Avergonzarse, ser confundido', 'Avergonzarse, ser confundido: experimentar vergüenza, humillación o esperanza frustrada en el Qal intransitivo. Casi siempre aparece en paralelo con בּוֹשׁ (Sal 35:4, 26; 71:24; Mi 3:7; Is 24:23), intensificando la expresión de desgracia total. Job 6:20 lo usa para las caravanas decepcionadas por wadis secos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98489, 'spa', 'Causar vergüenza, traer deshonra', 'Causar vergüenza, traer deshonra: el sentido causativo del Hifil, que inflige deshonra o reproche sobre otro. Proverbios lo emplea para la desgracia social dentro de las familias: un hijo que avergüenza a su padre (Pr 19:26) y quien actúa vergonzosamente (Pr 13:5). Isaías 33:9 e Is 54:4 extienden la fuerza causativa a tierras y pueblos humillados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98499, 'spa', 'Héfer (nombre propio)', 'El nombre propio Héfer (חֵפֶר), usado para al menos tres individuos distintos: principalmente el fundador del clan manasita cuyo linaje incluye a las hijas de Zelofehad (Núm 26:32; Jos 17:2), un judahíta en la genealogía de Asur (1 Cr 4:6) y un guerrero listado entre los héroes de David (1 Cr 11:36). Las versiones españolas emplean ''Héfer'' o ''Jéfer''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98507, 'spa', 'Disfrazarse — 7 ocurrencias, todas en la conjugación reflexiva Hitpael', 'Disfrazarse — 7 ocurrencias, todas en la conjugación reflexiva Hitpael. Reyes y líderes alteran su apariencia para evitar ser reconocidos: Saúl antes de visitar a la adivina de Endor (1 S 28:8), Acab entrando en batalla de incógnito (1 R 22:30) y la esposa de Jeroboam disfrazándose ante el profeta Ahías (1 R 14:2). La morfología reflexiva (''buscarse fuera de'' la propia identidad) es semánticamente reveladora.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98508, 'spa', 'El sentido activo central de buscar, escudriñar o investigar — 12 ocurrencias en', 'El sentido activo central de buscar, escudriñar o investigar — 12 ocurrencias en las conjugaciones Qal y Piel. Abarca desde la búsqueda física de posesiones (Gn 31:35, donde Labán registra la tienda de Raquel; Gn 44:12, el mayordomo de José registrando los sacos de los hermanos) hasta la investigación espiritual (Lm 3:40, ''escudriñemos nuestros caminos''). El español buscar/escudriñar y el francés chercher seleccionan ambos un vocabulario inquisitivo y deliberado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98510, 'spa', 'Ser escudriñado, expuesto o saqueado — 3 ocurrencias en las conjugaciones pasiva', 'Ser escudriñado, expuesto o saqueado — 3 ocurrencias en las conjugaciones pasivas Pual y Nifal. En Abdías 1:6, los tesoros ocultos de Esaú son ''escudriñados'' y expuestos por los enemigos. El Salmo 64:6 habla de las iniquidades que son ''bien escudriñadas'' — un ajuste de cuentas exhaustivo del que no se puede escapar. Proverbios 28:12 usa la voz pasiva para describir a la gente escondiéndose cuando los malvados se levantan.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98519, 'spa', 'Ser desfigurado o alterado en apariencia — una única ocurrencia en Job 30', 'Ser desfigurado o alterado en apariencia — una única ocurrencia en Job 30:18 donde Job describe su vestidura distorsionada por la violencia de su enfermedad. La forma Hitpael aquí pasa del disfraz deliberado (sentido 2) a la desfiguración involuntaria: la vestidura exterior de Job se tuerce y deforma, ciñéndolo como un collar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98530, 'spa', 'Morada de aislamiento', 'Vivienda separada o aislada, probablemente para cuarentena. 2 Reyes 15:5 y 2 Crónicas 26:21 describen al rey Uzías viviendo «en la casa de separación» tras ser herido con lepra, mientras su hijo gobernaba. El término enfatiza la separación de la sociedad y de los espacios sagrados por causa de impureza ritual. Las variantes textuales (ketiv y qere) reflejan incertidumbre antigua sobre la forma precisa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98531, 'spa', 'Libre, liberado, en libertad', 'Libre, liberado, en libertad: principalmente un término legal-social para la manumisión de esclavos hebreos. El Código de la Alianza ordena la liberación como חׇפְשִׁי en el séptimo año (Éx 21:2, 5, 26-27), y Deuteronomio 15:12-13, 18 repite el requisito con provisiones adicionales de generosidad. Jeremías 34:9-16 relata el pacto roto de manumisión bajo Sedequías. Isaías 58:6 extiende el concepto a toda forma de opresión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98535, 'spa', 'flecha, arma proyectil', 'flecha, arma proyectil');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98564, 'spa', 'Cantero, tallador de piedra — 8 ocurrencias usando el participio activo como des', 'Cantero, tallador de piedra — 8 ocurrencias usando el participio activo como designación ocupacional. Son los artesanos profesionales que extraían y labraban la piedra de construcción, especialmente prominentes en los relatos de la construcción del templo: 1 Reyes 5:15 enumera los canteros de Salomón; 1 Crónicas 22:2, 15 registra a David disponiendo canteros para preparar piedras labradas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98565, 'spa', 'Ser labrado o tallado — 4 ocurrencias usando formas pasivas (participio pasivo Q', 'Ser labrado o tallado — 4 ocurrencias usando formas pasivas (participio pasivo Qal, Nifal, Pual) que describen roca o material ya trabajado. Deuteronomio 6:11 y Nehemías 9:25 celebran las ''cisternas labradas'' como parte de la abundancia heredada en Canaán. Isaías 51:1 lo emplea memorablemente en metáfora: ''Mirad a la roca de donde fuisteis cortados'' — los orígenes de Israel trazados hasta Abraham y Sara.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98567, 'spa', 'Labrar, cortar o excavar en la roca — el sentido activo Qal central con 11 ocurr', 'Labrar, cortar o excavar en la roca — el sentido activo Qal central con 11 ocurrencias, abarcando el acto físico de cantear piedra, tallar cisternas, cavar lagares y excavar tumbas en la roca viva. Isaías 5:2 lo usa para labrar un lagar; Deuteronomio 8:9 para extraer cobre de los montes; 2 Crónicas 26:10 para las cisternas de Uzías en el desierto. El español ''cavaste'' y ''el que labra'' confirman la acción sobre material pétreo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98576, 'spa', 'Despedazar, hacer trozos — una única ocurrencia en Hifil en Isaías 51', 'Despedazar, hacer trozos — una única ocurrencia en Hifil en Isaías 51:9, donde se invoca al brazo del Señor como aquel que ''despedazó a Rahab'' (el monstruo primordial del caos). El español ''despedazó'' escala correctamente más allá del simple corte hacia la destrucción violenta. Esta intensificación causativa — del cuidadoso canteo al desmembramiento mítico — muestra la capacidad del verbo para la imaginería del guerrero divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98577, 'spa', 'Relampaguear, hendir el cielo — una única ocurrencia poética en el Salmo 29', 'Relampaguear, hendir el cielo — una única ocurrencia poética en el Salmo 29:7, donde la voz del Señor ''hiende llamas de fuego'', describiendo el rayo que parte los cielos. El español ''que corta'' y el alemán ''flashes hervor'' luchan por captar esta extensión meteorológica. La imagen transfiere la fuerza del cantero que parte la piedra al rayo de Yahvé — una brillante transferencia metafórica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98585, 'spa', 'Dividir, repartir', 'Dividir o repartir activamente (Qal). Jacob divide su gente y rebaños en dos campamentos (Gn 32:7; 33:1). La ley sobre el buey corneador exige dividir tanto el animal muerto como su precio (Éx 21:35). Moisés reparte el botín de guerra entre los combatientes y la congregación (Nm 31:27). El Qal activo coloca al agente en control directo de la distribución.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98586, 'spa', 'Ser dividido', 'Ser dividido o partido (Nifal pasivo). Elías golpea el Jordán y sus aguas ''se dividen'' (2 R 2:8), milagro que Eliseo repite (2 R 2:14). Ezequiel profetiza que Israel no volverá a ''ser dividido en dos reinos'' (Ez 37:22). Daniel prevé el imperio de Alejandro ''dividido hacia los cuatro vientos'' (Dn 11:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98588, 'spa', 'Partir los días', 'Partir por la mitad los días de vida, morir prematuramente (Qal idiomático). En Salmo 55:23, los impíos ''no vivirán la mitad de sus días''. Esta expresión extiende el acto físico de partir a la duración de la vida, creando una imagen memorable: el juicio de Dios corta el hilo de la existencia en su punto medio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98597, 'spa', 'Hazor (topónimo)', 'Hazor (topónimo): prominente ciudad real cananea en el norte de Galilea, llamada ''la cabeza de todos aquellos reinos'' (Jos 11:10), además de varios asentamientos menores que comparten el nombre. Josué derrotó al rey Jabín de Hazor y quemó la ciudad (Jos 11:1, 10-11, 13; 12:19). Un Jabín posterior oprimió a Israel hasta la victoria de Débora y Barac (Jue 4:2, 17). Salomón la reconstruyó como centro administrativo fortificado (1 R 9:15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98603, 'spa', 'Medianoche', 'La mitad de la noche, la hora de medianoche. Éxodo 11:4 anuncia que el juicio de Dios vendrá «como a la medianoche», señalando el momento preciso de la plaga. Job 34:20 describe la muerte repentina de los poderosos «a medianoche». Salmo 119:62 expresa devoción: «A medianoche me levanto para darte gracias». Las frases preposicionales muestran tanto referencias temporales aproximadas como exactas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98604, 'spa', 'mitad, porción fraccionaria', 'Una de dos partes iguales de cualquier totalidad mensurable: la mitad de la sangre (Éx 24:6), medio codo (Éx 25:10), la media tribu de Manasés (Jos 13:29), la mitad del reino (Est 5:3). Español mitad y francés moitié marcan uniformemente la lectura fraccionaria y cuantitativa. Este sentido abrumadoramente dominante (114×) abarca medidas cultuales, asignaciones territoriales y divisiones proporcionales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98615, 'spa', 'medio, punto central', 'El punto medio o centro de un lapso de tiempo o espacio, donde el foco recae en la posición central y no en una porción dividida. En Éx 12:29 «a la mitad de la noche» significa medianoche; español a medianoche y alemán bei Hälfte von confirman la lectura de centro temporal. Igualmente en 2 S 10:4 (vestidos cortados «por la mitad»), lo que importa es el punto de corte, no la porción resultante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98634, 'spa', 'Flecha, flechas', 'Proyectil disparado con arco, presente en narrativas de combate y en lenguaje metafórico. Aparece prominentemente en la escena de la señal entre Jonatán y David (1 S 20:20-38), donde el lugar donde cae la flecha comunica información de vida o muerte. También se usa del disparo letal de Jehú (2 R 9:24), la flecha simbólica de victoria de Eliseo (2 R 13:15-18) y la aflicción divina figurada como flechas que atraviesan al que sufre (Sal 38:2; Job 6:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98641, 'spa', 'Hierba, forraje, vegetación verde', 'Hierba, forraje, vegetación verde: hierba verde o crecimiento vegetal, usado literalmente como alimento para animales y figuradamente para la brevedad de la vida humana. Como pasto: Elías busca hierba para mantener vivos a los caballos durante la sequía (1 R 18:5), y Behemot come hierba como buey (Job 40:15). Como transitoriedad: ''toda carne es hierba'' (Is 40:6); los malvados florecen como hierba solo para perecer (Sal 37:2; 90:5; 103:15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98651, 'spa', 'Grava figurada', 'Grava o piedrecillas, usadas metafóricamente para consecuencias duras. Proverbios 20:17 advierte que el pan obtenido con engaño es dulce al principio, pero después «su boca se llenará de grava». Lamentaciones 3:16 se lamenta de que Dios «me quebró los dientes con cascajo», retratando el sufrimiento como algo áspero y penoso de soportar. Salmo 77:17 presenta un problema textual donde algunos manuscritos leen de forma diferente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98653, 'spa', 'Una trompeta de metal batido (clarín) usada para señalar asamblea, guerra y cele', 'Una trompeta de metal batido (clarín) usada para señalar asamblea, guerra y celebración litúrgica. Números 10:1-10 establece el monopolio sacerdotal sobre este instrumento y sus toques codificados: una nota larga para congregar, toque de alarma para la batalla, fanfarria jubilosa sobre los sacrificios. El Cronista amplía su papel en el culto del templo (2 Cr 5:12-13; 29:26-28), mientras Oseas 5:8 la empareja con el שׁוֹפָר en una alarma profética.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98663, 'spa', 'Tocar trompetas', 'Hacer sonar o tocar trompetas de plata en el culto levítico organizado, usado exclusivamente en Crónicas para contextos ceremoniales del templo: la procesión del arca (1 Cr 15:24), la dedicación del Templo (2 Cr 5:12-13), festivales sacrificiales (2 Cr 7:6), guerra santa (2 Cr 13:14) y la reforma de Ezequías (2 Cr 29:28). La forma participial mechatserim (''trompeteros'') y las variantes ortográficas Ketiv/Qere representan variación morfológica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98673, 'spa', 'atrio, patio, recinto', 'El espacio abierto cercado anexo a un edificio, especialmente los atrios del tabernáculo, del templo o de un palacio real. Este sentido abrumadoramente dominante (142 de 144 ocurrencias) se confirma por la estrecha convergencia interlingüística: spa el atrio, fra le parvis, deu der Vorhof. Pasajes clave incluyen las instrucciones sobre el atrio del tabernáculo en Éx 27:9-18 y el anhelo del salmista por los atrios de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98691, 'spa', 'aldea, asentamiento abierto', 'Un asentamiento o aldea sin muralla, atestiguado solo dos veces en 1 Cr 4:32-33 dentro de una lista de territorios tribales. El español pasa a aldeas en vez de atrio, y la forma plural marca claramente la distinción. Este sentido extiende el significado raíz de «cercamiento» hacia afuera —del patio amurallado al agrupamiento habitacional abierto— en paralelo con el elemento toponímico Hazar- en las listas geográficas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98707, 'spa', 'aldeas, caseríos', 'aldeas, caseríos');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98722, 'spa', 'Guerrero carmelita', 'Jetsro el carmelita, uno de los guerreros de elite de David. 2 Samuel 23:35 lo incluye entre los Treinta, con variación ketiv/qeré (Jetsro/Jetsrai). 1 Crónicas 11:37 ofrece la referencia paralela con ortografía ligeramente distinta. La designación «carmelita» sitúa su origen en Carmel de Judá. Las transliteraciones varían según el idioma, reflejando la dificultad de transmitir estos nombres propios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98723, 'spa', 'Hezrón (nombre de persona/lugar)', 'Hezrón (nombre de persona/lugar): nombre propio llevado por dos individuos y al menos un asentamiento. El rubenita Hezrón aparece en la genealogía de los descendientes de Jacob que migraron a Egipto (Gn 46:9; Éx 6:14; Nm 26:6; 1 Cr 5:3). El judahita Hezrón, hijo de Fares y nieto de Judá, es la figura más prominente: ancestro de David a través de Ram (Gn 46:12; Nm 26:21; Rt 4:18-19; 1 Cr 2:5, 9, 18, 21, 24-25; 4:1). Como topónimo, designa un lugar en la frontera sur de Judá (Jos 15:3, 25).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98729, 'spa', 'Hazerot (topónimo)', 'El nombre propio Hazerot (chatseroth), una estación en la ruta del éxodo de Israel entre Kibrot-hataavá y el desierto de Parán. Las traducciones multilingües lo transliteran uniformemente, confirmando un único referente geográfico. El sitio es conocido principalmente como escenario de la rebelión de Miriam contra Moisés (Núm 12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98738, 'spa', 'Asentamiento fronterizo noreste', 'Población que marca el límite noreste de la tierra prometida. En Números 34:9-10 define la frontera septentrional (''este será vuestro límite del norte''), mientras que Ezequiel 47:17 y 48:1 la sitúan en la línea entre Damasco y Hamat dentro de la distribución escatológica de la tierra. El nombre compuesto refleja tanto el elemento de recinto (חָצֵר) como el de manantiales (עֵינָן).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98739, 'spa', 'Asentamiento del Neguev', 'Poblado del Neguev asignado tanto a Judá como a Simeón, que aparece de forma constante en listas de ciudades a lo largo de cuatro libros bíblicos. El elemento animal שׁוּעָל (''zorro/chacal'') probablemente refleja la fauna del árido paisaje meridional. Las cuatro ocurrencias van precedidas de la conjunción copulativa, insertándolas siempre dentro de enumeraciones catalógicas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98740, 'spa', 'estatuto, ordenanza, decreto', 'Ley prescrita, ordenanza o estatuto establecido por autoridad divina o humana: el sentido dominante con 109 ocurrencias, columna vertebral del vocabulario legal de la Torá. En Éx 15:25 Dios establece para Israel «un estatuto y una ordenanza» en Mará; en Lv 26:46 los חֻקִּים son las regulaciones integrales dadas en el Sinaí. El plural חֻקִּים se empareja sistemáticamente con מִשְׁפָּטִים a lo largo de Deuteronomio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98753, 'spa', 'límite, frontera prescrita', 'Límite fijo, frontera o borde prescrito, típicamente del mar, la tierra o el orden cósmico (7 ocurrencias), concentradas en la poesía sapiencial y de creación. En Pr 8:29 la Sabiduría relata cómo Dios «puso un límite» (חֹק) al mar para que las aguas no traspasaran su mandato; en Job 26:10 Dios «trazó un límite» sobre la faz de las aguas. Job 14:5 aplica el concepto a la mortalidad humana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98755, 'spa', 'porción asignada, cuota', 'Parte asignada, porción prescrita o provisión regular, especialmente de alimentos, derechos sacerdotales o sustento (11 ocurrencias). En Gn 47:22 los sacerdotes egipcios tenían una «porción» (חֹק) de Faraón y comían de su ración, razón por la cual José no compró sus tierras. En Lv 10:13-14 se especifica la «cuota» sacerdotal de las ofrendas. Pr 30:8 ofrece la petición profundamente personal: «dame mi porción asignada».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98764, 'spa', 'lectura textual incierta', 'Una ocurrencia textualmente incierta en Sal 74:11, donde el texto consonántico masorético ha sido leído de modos diversos por distintas tradiciones. El Ketiv parece dar «tu seno» (חֵקְךָ, de חֵק «seno») en lugar de una forma de חֹק («estatuto»). Las traducciones en español e inglés vierten «tu seno», mientras el francés lee statut siguiendo otra vocalización.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98797, 'spa', 'Grabar o tallar figuras', 'Tallar o grabar figuras sobre una superficie, aplicado tanto a la decoración legítima del templo como a imágenes idolátricas ilícitas. El participio Pual מְחֻקֶּה describe las tallas en las puertas del templo de Salomón (1 R 6:35) y las imágenes abominables que Ezequiel ve grabadas en los muros (Ez 8:10; 23:14). En Job 13:27, el Hitpael desplaza el sentido hacia el acto de marcar un límite o frontera.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98798, 'spa', 'estatuto, ordenanza ritual', 'El sentido nuclear: un estatuto u ordenanza específica prescrita por Dios, vinculante como obligación permanente sobre Israel. Cubre los estatutos rituales de la Pascua (Éx 12:14, 43), las regulaciones sacerdotales (Éx 27:21; 28:43), el Día de la Expiación (Lv 16:29, 34) y la frase recurrente חֻקַּת עוֹלָם («estatuto perpetuo»). Incluye también los estatutos dados a los patriarcas (Gn 26:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98800, 'spa', 'ordenanzas naturales o de naciones', 'La forma plural empleada para las ordenanzas de la naturaleza o de las naciones: los decretos fijos que rigen el orden cósmico y social. Jer 5:24 habla de las «semanas señaladas» de la cosecha como חֻקּוֹת; Jer 31:35 nombra al sol y la luna como gobernados por חֻקּוֹת; Jer 33:25 invoca las חֻקּוֹת del cielo y la tierra. También incluye Jer 10:3 sobre las «costumbres de los pueblos» (prácticas paganas).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98806, 'spa', 'andar en estatutos ajenos', 'Construcción preposicional («en los estatutos de») usada para describir el seguir o imitar los estatutos de otro, típicamente en contexto negativo de Israel imitando a naciones extranjeras. Lv 20:23 advierte contra andar «en los estatutos de» las naciones; 1 Re 3:3 señala que Salomón andaba «en los estatutos de» David; 2 Re 17:8, 19 condenan a Israel por andar «en los estatutos de» las naciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98828, 'spa', 'Grabar, inscribir', 'Grabar, inscribir: la acción física primaria de cortar, tallar o inscribir marcas en una superficie duradera como piedra, metal o arcilla. En Proverbios 8:27 la Sabiduría contempla a Dios trazando un círculo sobre la faz del abismo en la creación, y en Isaías 30:8 se ordena al profeta escribir en una tablilla y grabarlo en un libro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98829, 'spa', 'Bastón de gobernante, cetro', 'Bastón de gobernante, cetro: extensión metonímica donde el participio Piel se refiere al bastón o cetro del gobernante, instrumento físico de quien graba la ley. En Génesis 49:10 aparece junto a ''cetro'' (שֵׁבֶט), y en Números 21:18 los nobles cavan un pozo ''con el cetro'' (בִּמְחֹקֵק).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98831, 'spa', 'Decretar, promulgar leyes', 'Decretar, promulgar leyes: el acto verbal de emitir decretos o promulgar estatutos con fuerza vinculante. En Proverbios 8:15 la sabiduría declara ''por mí reinan los reyes y los gobernantes decretan justicia'', y en Isaías 10:1 el profeta pronuncia un ay sobre ''los que decretan decretos inicuos''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98835, 'spa', 'Ser grabado, ser inscrito', 'Ser grabado, ser inscrito: el resultado pasivo del grabado, estar tallado o inscrito sobre una superficie. Job 19:23 expresa el deseo de que sus palabras ''sean inscritas en un libro'' y grabadas con cincel de hierro, mientras Ezequiel 23:14 describe figuras de caldeos grabadas en una pared.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98837, 'spa', 'Legislador, gobernante, jefe', 'Legislador, gobernante, jefe: usado sustantivamente para la persona que promulga legislación. Deuteronomio 33:21 habla de la porción del jefe reservada para el legislador, y Jueces 5:9 celebra a los jefes de Israel (חֹקְקֵי) que se ofrecieron voluntariamente para la batalla.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (98849, 'spa', 'Investigación activa o exploración de un asunto, lugar o situación para descubri', 'Investigación activa o exploración de un asunto, lugar o situación para descubrir la verdad. Jueces 18:2 envía espías a ''escudriñar'' la tierra, y David promete a Jonatán que ''sondeará'' las intenciones de su padre (1 S 20:12). La palabra implica exhaustividad — no una mirada casual sino una indagación sistemática. Deuteronomio 13:14 la empareja con ''inquirir'' y ''preguntar diligentemente'', formando una tríada legal de diligencia debida.');